/* ============================== QUESTIONS ============================== */
const fx=(o)=>mc({prompt:o.p,html:o.x,hint:o.h,video:o.v,topic:o.t,choices:o.c,keepOrder:o.k});

/* ---------- 🔍 Acid or Base? ---------- */
function catReason(chosen,s){const [f,cat,,why,name]=s;
 if(chosen===cat)return `${f} (${name}) ${why}.`+(cat==='WA'?` It is not on the strong-acid list (${STRONG_LIST}).`:'');
 if(isAcid(chosen)&&isAcid(cat))return chosen==='SA'?`${f} is not one of the six strong acids (${STRONG_LIST}), so it only partly ionizes: weak.`:`${f} is one of the six strong acids: it ionizes 100%, so it is strong, not weak.`;
 if(isBase(chosen)&&isBase(cat))return chosen==='SB'?`Strong bases are soluble hydroxides like NaOH or Ba(OH)₂. ${f} has no OH⁻ ion of its own and makes only a little OH⁻, so it is weak.`:`${f} is a soluble hydroxide: it releases all of its OH⁻ (100%), so it is strong.`;
 if(isAcid(chosen)&&isBase(cat))return `An acid gives off H⁺, but ${f} ${why}. That makes it a base.`;
 if(isBase(chosen)&&isAcid(cat))return `A base accepts H⁺ or releases OH⁻, but ${f} ${why}. That makes it an acid.`;
 if(cat==='N')return `${f} ${why}, so it is neither an acid nor a base.`;
 return `It is not neutral: ${f} ${why}.`}
function classifyQ(s){s=s||pickNew('cls',SUBST);return mc({topic:'id',video:isAcid(s[1])?'strength':'props',keepOrder:true,
 prompt:`Classify <b>${s[0]}</b> when it dissolves in water.`,html:`<div class="rxn">${s[0]}</div>`,
 hint:'Green sheet first: is it one of the six strong acids? Is it a soluble hydroxide (strong base)? Look for –COOH (weak acid), an amine N or CO₃²⁻/HCO₃⁻ (weak base). An alcohol –OH does not count as hydroxide.',
 choices:['SA','WA','SB','WB','N'].map(c=>[CAT_NAME[c],c===s[1],catReason(c,s)])})}
const ACID_FAM={binary:'Binary acid (H + one nonmetal)',oxy:'Oxyacid (H + an oxygen polyatomic ion)',carb:'Carboxylic acid (organic, –COOH)'};
const BASE_FAM={oh:'Ionic base with hydroxide, OH⁻',co3:'Ionic base with CO₃²⁻ or HCO₃⁻',amine:'Molecular base (N with a lone pair)'};
function familyQ(){const s=pickNew('fam',SUBST.filter(x=>x[1]!=='N')),[f,cat,fam,why]=s,acid=isAcid(cat);
 const rs={binary:[`${f} is H bonded to one nonmetal, with no oxygen: a binary acid.`,`A binary acid is just H plus one nonmetal, like HCl. ${f} ${fam==='carb'?'is a carbon compound with a –COOH group':'contains oxygen'}.`],
  oxy:[`${f} is H attached to a polyatomic ion that contains oxygen: an oxyacid.`,fam==='binary'?`An oxyacid contains oxygen, like H₂SO₄. ${f} has no oxygen.`:`${f} is organic (it has a –COOH group on carbon), so it is a carboxylic acid, not an oxyacid.`],
  carb:[`${f} is an organic molecule with a –COOH group: a carboxylic acid.`,`A carboxylic acid is organic, with a –COOH group on carbon. ${f} has no –COOH group.`],
  oh:[`${f} contains the hydroxide ion, OH⁻.`,`${f} has no hydroxide ion (OH⁻).`],
  co3:[`${f} ${why}.`,`${f} has no carbonate (CO₃²⁻) or bicarbonate (HCO₃⁻) ion.`],
  amine:[`${f} is a molecule with an N lone pair (ammonia or an amine) that accepts H⁺.`,`${f} is ionic: it is not a molecule with an amine N.`]};
 const F=acid?ACID_FAM:BASE_FAM,ch=Object.keys(F).map(k=>[F[k],k===fam,rs[k][k===fam?0:1]]);
 ch.push([acid?'Not an acid: it is a base':'Not a base: it is an acid',false,`${f} ${why}, so it is ${acid?'an acid':'a base'}.`]);
 return mc({topic:'id',video:'props',keepOrder:true,prompt:`<b>${f}</b> is ${acid?'an acid':'a base'}. What kind?`,html:`<div class="rxn">${f}</div>`,
  hint:acid?'Binary acids: H + one nonmetal (HCl). Oxyacids: H + an ion with oxygen (H₂SO₄). Carboxylic acids: organic with –COOH.':'Ionic bases contain OH⁻ or CO₃²⁻/HCO₃⁻. Molecular bases are ammonia and amines (–NH₂): the N lone pair grabs H⁺.',choices:ch})}
function strongPickQ(){if(Math.random()<0.6){const r=pick(SUBST.filter(x=>x[1]==='SA')),w=shuf(SUBST.filter(x=>x[1]==='WA')).slice(0,3);
  return mc({topic:'strong',video:'strength',prompt:'Which one is a <b>strong acid</b>?',hint:`Memorize the six strong acids: ${STRONG_LIST}. Every other acid is weak.`,
   choices:[[r[0],true,`${r[0]} is one of the six strong acids (${STRONG_LIST}): it ionizes 100% in water.`],...w.map(x=>[x[0],false,`${x[0]} ${x[3]}. That makes it a weak acid.`])]})}
 const r=pick(SUBST.filter(x=>x[1]==='SB')),pool=[['NH₃','NH₃ is a weak base: its N lone pair accepts H⁺, making only a little OH⁻. It has no OH⁻ of its own.'],['NaHCO₃','NaHCO₃ (baking soda) is a weak base: HCO₃⁻ accepts H⁺ but makes only a little OH⁻.'],['CH₃OH','CH₃OH is an alcohol: its O–H is a covalent bond, so it releases no OH⁻. It is not a base.'],['Mg(OH)₂','Mg(OH)₂ (milk of magnesia) barely dissolves in water, so it cannot release much OH⁻. Strong bases are soluble hydroxides.'],['CH₃NH₂','CH₃NH₂ is an amine: a weak base that makes only a little OH⁻.'],['Na₂CO₃','Na₂CO₃ is a weak base: CO₃²⁻ accepts H⁺ but makes only a little OH⁻.']];
 return mc({topic:'strong',video:'strength',prompt:'Which one is a <b>strong base</b>?',hint:'Strong bases are soluble hydroxides: Group 1 hydroxides (LiOH, NaOH, KOH) plus Ca(OH)₂, Sr(OH)₂ and Ba(OH)₂.',
  choices:[[r[0],true,`${r[0]} is a soluble hydroxide: it releases all of its OH⁻ in water, so it is a strong base.`],...shuf(pool).slice(0,3).map(x=>[x[0],false,x[1]])]})}
const PROPS=[
 {p:'A solution tastes <b>sour</b> and turns blue litmus paper <b>red</b>. It is most likely…',h:'Sour taste and red litmus go together.',v:'props',c:[['An acid',true,'Acids taste sour and turn litmus red (Lecture 26 properties table).'],['A base',false,'Bases taste bitter and turn litmus blue.'],['A neutral salt solution',false,'A neutral solution would not change blue litmus to red.'],['Pure water',false,'Pure water is neutral (pH 7): no color change.']]},
 {p:'An unknown solution turned <b>pink</b> when a drop of phenolphthalein was added. Is it HNO₃ or KOH?',h:'Phenolphthalein is pink in base and colorless in acid.',v:'props',c:[['KOH, because pink means basic',true,'Phenolphthalein turns pink in base. KOH is a strong base.'],['HNO₃, because pink means acidic',false,'Phenolphthalein is colorless in acid; pink means base.'],['Either one; the color tells nothing',false,'The color tells us a lot: pink only happens in base.'],['Neither; pink means neutral',false,'Phenolphthalein is colorless at neutral pH 7.']]},
 {p:'An unknown solution turned litmus paper <b>red</b>. Is it HBr(aq) or Ba(OH)₂(aq)?',h:'Red litmus = acid; blue litmus = base.',v:'props',c:[['HBr, because red litmus means acid',true,'Acids turn litmus red. HBr is a strong acid.'],['Ba(OH)₂, because red litmus means base',false,'Bases turn litmus blue, not red.'],['Both would turn litmus red',false,'Ba(OH)₂ is a base: it turns litmus blue.'],['Neither; red litmus means neutral',false,'Neutral solutions leave litmus purple (no change).']]},
 {p:'A cleaning solution feels <b>slippery/soapy</b> and tastes bitter. It is most likely…',h:'Which one is bitter and soapy?',v:'props',c:[['A base',true,'Bases taste bitter and feel slippery or soapy.'],['An acid',false,'Acids taste sour, not bitter.'],['A neutral salt',false,'Salt solutions are not slippery.'],['A strong acid',false,'Strong acids are sour and corrosive, not soapy.']]},
 {p:'A strip of magnesium metal fizzes and gives off H₂ gas in a solution. The solution is…',h:'Which kind of substance "dissolves" (corrodes) metals?',v:'props',c:[['Acidic',true,'Acids corrode some metals: M + acid → salt + H₂(g), like Mg + 2 HCl → MgCl₂ + H₂.'],['Basic',false,'Bases do not react with Mg to give H₂; acids do.'],['Neutral',false,'A neutral solution would not corrode the metal.'],['Pure ethanol',false,'Ethanol is not an acid; it would not make H₂ with Mg.']]},
 {p:'Why do solutions of acids and bases <b>conduct electricity</b>?',h:'What do acids and bases make when they dissolve?',v:'props',c:[['They make ions in water',true,'Acids and bases dissociate into ions (H⁺ and A⁻, or M⁺ and OH⁻), so their solutions are electrolytes.'],['They contain metal atoms',false,'Many acids (HCl) have no metal at all. Moving ions carry the current.'],['They are always hot',false,'Temperature is not why they conduct; ions are.'],['Their molecules stay whole',false,'Whole molecules do not carry charge. Ions do.']]},
 {p:'When H⁺ is released into water, it immediately joins a water molecule. What forms?',h:'H₂O + H⁺ → ?',v:'props',c:[['H₃O⁺, the hydronium ion',true,'H₂O + H⁺ → H₃O⁺. That is why [H⁺] and [H₃O⁺] mean the same thing.'],['OH⁻, the hydroxide ion it releases',false,'OH⁻ forms when water loses an H⁺, not gains one.'],['H₂ gas',false,'H₂ gas forms when an acid reacts with a metal, not in plain water.'],['H₂O₂, peroxide',false,'Adding H⁺ to water does not add an O atom.']]},
 {p:'<b>Aspirin</b> has a –COOH group (and an ester group). In water, aspirin acts as…',h:'What does –COOH do?',v:'props',c:[['An acid',true,'The –COOH (carboxylic acid) group gives off H⁺. Aspirin is acetylsalicylic acid.'],['A base',false,'A base needs OH⁻, CO₃²⁻ or an amine N to accept H⁺. Aspirin has none of those.'],['Neither',false,'The –COOH group makes it an acid.'],['A strong base',false,'Aspirin has no hydroxide ion; it is a weak acid.']]},
 {p:'<b>Isoamyl acetate</b> (banana flavor) is an ester: it has –COO– but no –COOH and no N. In water it is…',h:'Does it have an acidic –COOH hydrogen or an amine N?',v:'props',c:[['Neither an acid nor a base',true,'An ester has no –COOH hydrogen to give off and no N lone pair to grab H⁺.'],['An acid, because it has O atoms',false,'O atoms alone do not make an acid; it needs a –COOH hydrogen.'],['A base, because it has C–H bonds',false,'C–H hydrogens are not given off and do not accept H⁺.'],['A strong acid',false,'It is not one of the six strong acids, and it is not an acid at all.']]},
 {p:'<b>Pseudoephedrine</b> (a decongestant) has an –NH– amine group. In water it acts as…',h:'What does the lone pair on an amine N do?',v:'props',c:[['A weak base',true,'The amine N lone pair accepts H⁺ to become an ammonium ion: a weak base.'],['A weak acid',false,'An amine accepts H⁺; it does not give it off.'],['A strong base',false,'Strong bases are soluble hydroxides like NaOH. Amines are weak bases.'],['Neither',false,'The amine N makes it a base.']]},
 {p:'<b>Ibuprofen</b> has a –COOH group on its ring. In water it acts as…',h:'Look for –COOH.',v:'props',c:[['A weak acid',true,'The –COOH group gives off a little H⁺: a weak (carboxylic) acid.'],['A strong acid',false,'Only six acids are strong (HCl, HBr, HI, HNO₃, H₂SO₄, HClO₄). Ibuprofen is weak.'],['A weak base',false,'It has no amine N or carbonate to accept H⁺.'],['Neither',false,'The –COOH group makes it an acid.']]},
 {p:'A <b>strong</b> acid makes a <b>strong electrolyte</b> solution. Why?',h:'Strong = how much it dissociates.',v:'strength',c:[['It dissociates completely into ions',true,'Strong acids break apart 100% into H⁺ and A⁻: many ions, bright bulb.'],['It is always very concentrated',false,'Strength is about % dissociation, not concentration. Even dilute HCl is strong.'],['It has many H atoms in it',false,'CH₄ has 4 H atoms and is not an acid. Strength is about dissociation.'],['Its molecules stay whole in water',false,'That describes a weak acid (few ions).']]}];
const SEE={SA:'only ions (lots of H₃O⁺ and A⁻, no whole HA) and a bright bulb',WA:'mostly whole HA molecules with only a few H₃O⁺ ions, and a dim bulb',SB:'only ions (lots of M⁺ and OH⁻) and a bright bulb',WB:'mostly whole B molecules with a few BH⁺ and OH⁻ ions, and a dim bulb',N:'only whole molecules (no ions) and a bulb that stays off'};
const BEAKER_OK=s=>s[1]==='WB'?s[2]==='amine':s[1]==='N'?/OH|C₆H₁₂O₆|COOCH₃/.test(s[0])&&!/^(NaCl|KNO₃)$/.test(s[0]):true;
function beakerQ(){const cat=pick(['SA','WA','SB','WB','N']),others=shuf(['SA','WA','SB','WB','N'].filter(c=>c!==cat)).slice(0,3);
 const of=c=>pick(SUBST.filter(s=>s[1]===c&&BEAKER_OK(s)));const r=of(cat);
 return mc({topic:'strong',video:'strength',lab:{kind:'beaker',cfg:{cat}},task:{need:'bulb',say:'Tap <b>💡 Test conductivity</b>, then look at the particles.'},
  prompt:'This beaker holds one substance dissolved in water. Which substance could it be?',
  hint:'Ions = the substance split apart (strong). Mostly whole molecules with a few ions = weak. No ions at all = nonelectrolyte. H₃O⁺ means acid; OH⁻ means base.',
  choices:[[r[0],true,`${r[0]} is a ${CAT_NAME[cat].toLowerCase()}: it gives ${SEE[cat]}. That matches this beaker.`],...others.map(c=>{const s=of(c);return [s[0],false,`${s[0]} is ${c==='N'?'not an acid or base':'a '+CAT_NAME[c].toLowerCase()}: it would give ${SEE[c]}.`]})]})}
function idQ(){const r=Math.random();if(r<0.1)return ionConcQ();if(r<0.3)return classifyQ();if(r<0.45)return familyQ();if(r<0.6)return strongPickQ();if(r<0.8)return beakerQ();return fx(pickNew('props',PROPS))}

/* ---------- 🌈 pH Lab ---------- */
const IND_NAME={litmus:'Litmus paper',phth:'Phenolphthalein'};
const IND_RULE={litmus:{Red:'Litmus turns red in acid (below about pH 5).',Blue:'Litmus turns blue in base (above about pH 8).','Purple (in between)':'Litmus stays purple only near neutral (about pH 5 to 8).',Colorless:'Litmus paper is never colorless: it is red, blue, or purple in between.'},
 phth:{Colorless:'Phenolphthalein is colorless in acidic and neutral solutions (below pH 8.2).','Light pink':'Phenolphthalein turns light pink just above pH 8.2.','Dark pink':'Phenolphthalein turns dark pink in strongly basic solutions (above about pH 10.8).',Blue:'Phenolphthalein never turns blue: it goes from colorless to pink.'}};
function phColorQ(){const ind=pick(['litmus','phth']),ok=h=>ind==='litmus'?(h[1]<4.6||h[1]>8.5):(h[1]<7.8||(h[1]>8.6&&Math.abs(h[1]-10.8)>0.6));const h=pick(HOUSE.filter(ok)),col=(ind==='litmus'?litmus:phth)(h[1])[2],R=IND_RULE[ind];
 return mc({topic:'ind',video:'ind',lab:{kind:'ph',cfg:{pH0:7,ind:'uni'}},task:{need:L=>L.picked===h[0]&&L.ind===ind,say:`Pick <b>${h[2]} ${h[0]}</b> from the list, then tap <b>${ind==='litmus'?'Litmus':'Phenolphthalein'}</b>.`},
  prompt:`What color does ${IND_NAME[ind].toLowerCase()} show in ${h[0].toLowerCase()}?`,hint:ind==='litmus'?'Litmus: red in acid, blue in base.':'Phenolphthalein: colorless in acid, pink in base (starting at pH 8.2).',
  choices:Object.keys(R).map(k=>[k,k===col,k===col?`${h[0]} has pH ${h[1].toFixed(2)} (${acidity(h[1])}). ${R[k]}`:`${R[k]} ${h[0]} is pH ${h[1].toFixed(2)}.`])})}
function pOHLabQ(){const t=pick([1,2,3,4,5,6,8,9,10,11,12,13]),f=x=>x.toFixed(2);
 return mc({topic:'phc',video:'ph',lab:{kind:'ph',cfg:{pH0:7,ind:'uni'}},task:{need:L=>Math.abs(L.pH-t)<0.001,say:`Slide the pH to exactly <b>${t}.0</b>. Watch the four corners.`},
  prompt:`At pH ${t}.00, what is the pOH?`,hint:'pH + pOH = 14.00 at 25 °C.',
  choices:[[f(14-t),true,`pOH = 14.00 − pH = 14.00 − ${t}.00 = ${f(14-t)}.`],[f(t),false,`That is the pH. pOH = 14.00 − pH.`],['7.00',false,'pOH is 7.00 only when the solution is neutral (pH 7.00).'],[f(14+t),false,'Subtract, don\'t add: pOH = 14.00 − pH.']]})}
function ratioLabQ(){const d=pick([1,2,2,3]),a=pick(d===3?[2,3,9,10]:[2,3,4,9,10]),b=a+d;const T=n=>Number(n).toLocaleString('en-US')+'×';
 const ch=[[T(10**d),true,`Each pH unit is a 10× change in [H⁺]. ${d} unit${d>1?'s':''} apart → 10${d>1?supN(d):''} = ${T(10**d)} more H⁺ at the lower pH.`],[T(10**(d+1)),false,`That would be ${d+1} pH units apart. These are ${d} apart.`],
  [d===1?'2×':T(d),false,'pH is a log scale: each 1 pH step is 10×, not 1× more.'],[d===1?'1× (the same)':T(10**(d-1)),false,d===1?'Different pH values always mean different [H⁺].':`That would be ${d-1} pH unit${d-1>1?'s':''} apart. These are ${d} apart.`]];
 return mc({topic:'ind',video:'ph',lab:{kind:'ph',cfg:{pH0:7,ind:'uni'}},task:{need:L=>L.seen.has(a)&&L.seen.has(b),say:`Slide to pH <b>${a}.0</b>, then to pH <b>${b}.0</b>. Watch the [H⁺] corner.`},
  prompt:`How many times more H⁺ is in a solution at pH ${a} than at pH ${b}?`,hint:'Compare the exponents in the [H⁺] corner. Each pH unit is a power of 10.',choices:ch})}
function pinkLabQ(){return mc({topic:'ind',video:'props',lab:{kind:'ph',cfg:{pH0:7,ind:'uni'}},task:{need:L=>L.ind==='phth'&&[...L.seen].some(v=>v>=8.2&&v<=8.6),say:'Tap <b>Phenolphthalein</b>, then slide slowly from pH 7 up to about pH 8.5.'},
 prompt:'At about what pH does phenolphthalein <b>first</b> turn pink?',hint:'Watch the beaker as you pass pH 8.',
 choices:[['About 8.2',true,'Phenolphthalein is colorless below pH 8.2 and turns pink above it. That is why it works for titration endpoints.'],['Exactly 7.0',false,'At pH 7 (neutral) phenolphthalein is still colorless.'],['About 5.0',false,'pH 5 is acidic; phenolphthalein is colorless in acid.'],['About 12.0',false,'It is already pink well before pH 12.']]})}
function bloodLabQ(){return mc({topic:'ind',video:'ph',lab:{kind:'ph',cfg:{pH0:7,ind:'uni'}},task:{need:L=>L.picked==='Human blood',say:'Pick <b>🩸 Human blood</b> from the list.'},
 prompt:'Human blood is pH 7.40. How would you describe it?',hint:'Below 7 is acidic, above 7 is basic. How far from 7 is it?',
 choices:[['Slightly basic',true,'7.40 is just above 7.00, so [OH⁻] is a little higher than [H⁺]: slightly basic. Normal arterial blood is 7.35–7.45.'],['Exactly neutral',false,'Neutral is exactly 7.00. Blood is 7.40.'],['Slightly acidic',false,'Acidic means below 7.00. Blood is above 7.'],['Strongly basic',false,'Strongly basic is far above 7 (like bleach, 12.5). Blood is only 0.40 above.']]})}
function waterLabQ(){return mc({topic:'phc',video:'kw',lab:{kind:'ph',cfg:{pH0:4,ind:'uni'}},task:{need:L=>L.picked==='Pure water',say:'Pick <b>💧 Pure water</b> from the list. Read the [H⁺] corner.'},
 prompt:'What is [H⁺] in pure water at 25 °C?',hint:'In neutral water [H⁺] = [OH⁻], and [H⁺][OH⁻] = 1.0 × 10⁻¹⁴.',
 choices:[['1.0 × 10⁻⁷ M',true,'Water autoionizes a tiny bit. [H⁺] = [OH⁻] = x and x² = 1.0 × 10⁻¹⁴, so x = 1.0 × 10⁻⁷ M.'],['1.0 × 10⁻¹⁴ M',false,'1.0 × 10⁻¹⁴ is K<sub>w</sub>, the product [H⁺][OH⁻], not [H⁺] itself.'],['7.0 M',false,'7 is the pH, not the concentration. [H⁺] = 10⁻⁷ M.'],['0 M (no ions)',false,'Water autoionizes: a few molecules act as acids and a few as bases.']]})}
function concClassQ(){const useH=Math.random()<0.5,n=pick([2,3,4,5,6,8,9,10,11,12]),m=rnd(11,99)/10,v=m*10**-n,ans=useH?(v>1e-7?'acidic':'basic'):(v>1e-7?'basic':'acidic');
 const oh=KW/v,ion=useH?'[H⁺]':'[OH⁻]',other=useH?'[OH⁻]':'[H⁺]';
 return mc({topic:'ind',video:'strength',prompt:`A solution has ${ion} = ${sci(v,2)} M. Is it acidic, basic, or neutral?`,hint:'Compare to neutral water, 1.0 × 10⁻⁷ M. More H⁺ than that = acidic; more OH⁻ = basic.',keepOrder:true,
  choices:[['Acidic',ans==='acidic',ans==='acidic'?`${ion} ${useH?'> 10⁻⁷ M, so H⁺ is above neutral':'< 10⁻⁷ M, so OH⁻ is below neutral and H⁺ is above'}: acidic. (${other} = ${sci(oh,2)} M.)`:`Acidic needs [H⁺] above 10⁻⁷ M. Here ${other} = ${sci(oh,2)} M.`],
   ['Basic',ans==='basic',ans==='basic'?`${ion} ${useH?'< 10⁻⁷ M, so H⁺ is below neutral and OH⁻ is above':'> 10⁻⁷ M, so OH⁻ is above neutral'}: basic. (${other} = ${sci(oh,2)} M.)`:`Basic needs [OH⁻] above 10⁻⁷ M. Here ${useH?'[OH⁻]':'[OH⁻]'} = ${sci(useH?oh:v,2)} M.`],
   ['Neutral',false,`Neutral means [H⁺] = [OH⁻] = 1.0 × 10⁻⁷ M. ${ion} is ${sci(v,2)} M.`]]})}
const PH_IDEAS=[
 {p:'As you add acid to water, [H⁺] goes up. What happens to [OH⁻]?',h:'[H⁺][OH⁻] = 1.0 × 10⁻¹⁴ always.',v:'strength',t:'phc',c:[['It goes down',true,'[H⁺] × [OH⁻] stays 1.0 × 10⁻¹⁴, so when one goes up the other must go down (inverse relationship).'],['It goes up too',false,'If both went up, their product would grow past 1.0 × 10⁻¹⁴. They move in opposite directions.'],['It stays the same',false,'The product must stay 1.0 × 10⁻¹⁴, so [OH⁻] must change.'],['It becomes zero',false,'[OH⁻] gets very small but never zero.']]},
 {p:'pH 2 vs. pH 3: which is more acidic, and by how much?',h:'Lower pH = more acidic. Each pH unit = 10×.',v:'ph',t:'ind',c:[['pH 2, 10× more acidic',true,'Lower pH is more acidic, and one pH unit is a factor of 10 in [H⁺].'],['pH 3, 10× more acidic',false,'Higher pH means less H⁺. pH 2 is more acidic.'],['pH 2, 2× more acidic',false,'pH is a log scale: 1 unit is 10×, not 2×.'],['They are the same',false,'Different pH values have different [H⁺].']]},
 {p:'pH 10 vs. pH 7: how much more basic is pH 10?',h:'Count the pH units; each one is 10×.',v:'ph',t:'ind',c:[['1000× more basic',true,'3 pH units apart: 10 × 10 × 10 = 1000× (Lecture 26 slide 23).'],['3× more basic than pH 7',false,'pH is a log scale; 3 units is 10³, not 3.'],['30× more basic',false,'Multiply by 10 for each unit: 10³ = 1000.'],['100× more basic',false,'That is 2 units. 10 − 7 = 3 units.']]},
 {p:'[H⁺] = 1.5 × 10⁻⁷ M. How many <b>decimal places</b> should the pH have?',h:'Log rule: decimal places in the log = sig figs in the number.',v:'log',t:'phc',c:[['2 (pH = 6.82)',true,'1.5 has 2 sig figs, so the pH gets 2 decimal places: 6.82.'],['1 (pH = 6.8)',false,'Count sig figs in 1.5 × 10⁻⁷: two (1 and 5). So 2 decimal places.'],['3 (pH = 6.824)',false,'Only 2 sig figs in 1.5, so only 2 decimal places.'],['0 (pH = 7)',false,'Rounding to a whole number throws away measured digits.']]},
 {p:'At 25 °C, pH + pOH equals…',h:'Take −log of [H⁺][OH⁻] = 1.0 × 10⁻¹⁴.',v:'ph',t:'phc',c:[['14.00',true,'−log(1.0 × 10⁻¹⁴) = 14.00, so pH + pOH = 14.00.'],['7.00',false,'7.00 is the pH of neutral water, not the sum.'],['1.0 × 10⁻¹⁴',false,'That is the product [H⁺][OH⁻] (K<sub>w</sub>), not pH + pOH.'],['0',false,'pH and pOH are both positive for normal solutions.']]},
 {p:'Arterial blood should be pH 7.35–7.45. A patient\'s blood is pH 7.30. This is…',h:'Below the normal range is more acidic than normal.',v:'ph',t:'ind',c:[['Acidosis',true,'7.30 is below 7.35: the blood is too acidic (acidosis), even though 7.30 is above 7.'],['Alkalosis',false,'Alkalosis is above 7.45 (too basic).'],['Normal',false,'Normal is 7.35–7.45; 7.30 is below.'],['Neutral',false,'Neutral is exactly 7.00; blood is judged against its own normal range.']]},
 {p:'Which indicator result tells you a solution is <b>basic</b>?',h:'Litmus: red/blue. Phenolphthalein: colorless/pink.',v:'props',t:'ind',c:[['Phenolphthalein turns pink',true,'Phenolphthalein is pink in base (above pH 8.2).'],['Litmus turns red',false,'Red litmus means acid.'],['Phenolphthalein stays colorless',false,'Colorless phenolphthalein means acidic or neutral.'],['Litmus stays purple',false,'Purple litmus is the in-between color near neutral.']]}];
