/* ---------- 🧮 pH Calculator (typed) ---------- */
const mant=s=>s===3?rnd(101,999)/100:rnd(11,99)/10;
const f2=x=>x.toFixed(2);
const CORNERS='<div class="mini4"><span>pH</span><span>⇄ 14.00 − ⇄</span><span>pOH</span><span>↕ −log / 10⁻ˣ</span><span></span><span>↕ −log / 10⁻ˣ</span><span>[H⁺]</span><span>⇄ K<sub>w</sub> ÷ ⇄</span><span>[OH⁻]</span></div>';
function calcQ(kind){kind=kind||pick(['pHH','pHH','pOHOH','Hfrom','HfrompOH','OHfromH','pOHfrompH','pHfromOH','sa','sb','sb']);const s=pick([2,2,3]);let q;
 const logQ=(o)=>Object.assign({type:'num',kind:'log',topic:'phc',video:'ph',html:CORNERS},o),concQ=(o)=>Object.assign({type:'num',kind:'conc',topic:'conc',video:'log',unit:'M',html:CORNERS},o);
 if(kind==='pHH'){const h=mant(s)*10**-rnd(2,12),a=pHof(h);q=logQ({prompt:`[H⁺] = ${sci(h,s)} M. What is the pH?`,answer:a,dp:s,hint:'pH = −log[H⁺]. Then round: decimal places in pH = sig figs in [H⁺].',
  why:`pH = −log(${sci(h,s)}) = <b>${a.toFixed(s)}</b>. ${s} sig figs in [H⁺] → ${s} decimal places in pH. ${a<7?'Acidic':'Basic'}.`,slips:[[-a,'You dropped the minus sign: pH = <b>−</b>log[H⁺].'],[14-a,'That is the pOH. pH = −log[H⁺] directly.'],[-Math.log(h),'Use log (base 10), not ln.']]})}
 else if(kind==='pOHOH'){const o=mant(s)*10**-rnd(2,12),a=pHof(o);q=logQ({prompt:`[OH⁻] = ${sci(o,s)} M. What is the pOH?`,answer:a,dp:s,hint:'pOH = −log[OH⁻]. Decimal places = sig figs in [OH⁻].',
  why:`pOH = −log(${sci(o,s)}) = <b>${a.toFixed(s)}</b>.`,slips:[[-a,'You dropped the minus sign: pOH = <b>−</b>log[OH⁻].'],[14-a,'That is the pH. The question asks for pOH = −log[OH⁻].'],[-Math.log(o),'Use log (base 10), not ln.']]})}
 else if(kind==='Hfrom'){const p=rnd(100,1300)/100,a=10**-p;q=concQ({prompt:`A solution has pH = ${f2(p)}. What is [H⁺]?`,answer:a,sf:2,video:'inv',hint:'[H⁺] = 10<sup>−pH</sup>. Two decimal places in the pH → 2 sig figs in [H⁺].',
  why:`[H⁺] = 10<sup>−${f2(p)}</sup> = <b>${nf(a,2)} M</b>. 2 decimal places in pH → 2 sig figs.`,slips:[[10**p,'Use a <b>negative</b> exponent: [H⁺] = 10<sup>−pH</sup>.'],[10**-(14-p),'That is [OH⁻]. [H⁺] = 10<sup>−pH</sup>.'],[-Math.log10(p),'Use the inverse log (10ˣ), not log.']]})}
 else if(kind==='HfrompOH'){const po=rnd(100,1300)/100,a=10**-(14-po);q=concQ({prompt:`A solution has pOH = ${f2(po)}. What is [H₃O⁺]?`,answer:a,sf:2,video:'inv',hint:'Two steps: pH = 14.00 − pOH, then [H₃O⁺] = 10<sup>−pH</sup>.',
  why:`pH = 14.00 − ${f2(po)} = ${f2(14-po)}; [H₃O⁺] = 10<sup>−${f2(14-po)}</sup> = <b>${nf(a,2)} M</b>. ${14-po<7?'Acidic':'Basic'}.`,slips:[[10**-po,'That is [OH⁻] (10<sup>−pOH</sup>). Find the pH first: pH = 14.00 − pOH.'],[10**(14-po),'Use a negative exponent: [H₃O⁺] = 10<sup>−pH</sup>.']]})}
 else if(kind==='OHfromH'){const h=mant(s)*10**-rnd(2,12),a=KW/h;q=concQ({prompt:`[H⁺] = ${sci(h,s)} M. What is [OH⁻]?`,answer:a,sf:s,hint:'[H⁺][OH⁻] = 1.0 × 10⁻¹⁴, so [OH⁻] = 1.0 × 10⁻¹⁴ ÷ [H⁺].',
  why:`[OH⁻] = 1.0 × 10⁻¹⁴ ÷ ${sci(h,s)} = <b>${nf(a,s)} M</b>.`,slips:[[KW*h,'Divide by [H⁺]; don\'t multiply.'],[h/KW,'Flip it: [OH⁻] = 1.0 × 10⁻¹⁴ ÷ [H⁺].'],[h,'That is [H⁺] again. Use K<sub>w</sub> to find [OH⁻].']]})}
 else if(kind==='pOHfrompH'){const p=rnd(100,1300)/100;q=logQ({prompt:`A solution has pH = ${f2(p)}. What is the pOH?`,answer:14-p,dp:2,hint:'pH + pOH = 14.00.',why:`pOH = 14.00 − ${f2(p)} = <b>${f2(14-p)}</b>.`,slips:[[p,'That is the pH. Subtract it from 14.00.'],[14+p,'Subtract, don\'t add: pOH = 14.00 − pH.']]})}
 else if(kind==='pHfromOH'){const o=mant(s)*10**-rnd(2,12),poh=pHof(o),a=14-poh;q=logQ({prompt:`[OH⁻] = ${sci(o,s)} M. What is the <b>pH</b>?`,answer:a,dp:s,hint:'Two steps: pOH = −log[OH⁻], then pH = 14.00 − pOH.',
  why:`pOH = −log(${sci(o,s)}) = ${poh.toFixed(s)}; pH = 14.00 − ${poh.toFixed(s)} = <b>${a.toFixed(s)}</b>.`,slips:[[poh,'That is the pOH. One more step: pH = 14.00 − pOH.'],[-poh,'Keep the minus sign in −log, then subtract from 14.00.']]})}
 else if(kind==='sa'){const ac=pick(['HCl','HBr','HI','HNO₃','HClO₄']),c=mant(s)*10**-rnd(1,4),a=pHof(c);q=logQ({topic:'phc',prompt:`What is the pH of ${sci(c,s)} M ${ac}(aq)?`,answer:a,dp:s,video:'strength',hint:`${ac} is a strong acid: it ionizes 100%, so [H⁺] = [${ac}].`,
  why:`${ac} is strong, so [H⁺] = ${sci(c,s)} M. pH = −log(${sci(c,s)}) = <b>${a.toFixed(s)}</b>.`,slips:[[14-a,'That is the pOH. For an acid, pH = −log[H⁺].'],[-a,'You dropped the minus sign.'],[14+Math.log10(c),'An acid gives H⁺, not OH⁻: pH = −log[H⁺].']]})}
 else{const b=pick(SUBST.filter(x=>x[1]==='SB')),n=/\(OH\)₂/.test(b[0])?2:1,c=mant(s)*10**-rnd(2,4),poh=pHof(n*c),a=14-poh;
  q=logQ({topic:'phc',prompt:`What is the pH of ${sci(c,s)} M ${b[0]}(aq)?`,answer:a,dp:s,video:'stoich',hint:`${b[0]} is a strong base${n===2?' and each unit releases <b>2</b> OH⁻':''}. Find [OH⁻], then pOH, then pH = 14.00 − pOH.`,
   why:`[OH⁻] = ${n===2?'2 × ':''}${sci(c,s)} = ${sci(n*c,s)} M; pOH = ${poh.toFixed(s)}; pH = 14.00 − ${poh.toFixed(s)} = <b>${a.toFixed(s)}</b>.`,
   slips:[[poh,'That is the pOH. Finish with pH = 14.00 − pOH.'],...(n===2?[[14+Math.log10(c),`Each ${b[0]} releases 2 OH⁻, so [OH⁻] = 2 × ${sci(c,s)} M.`]]:[]),[-Math.log10(c),'A base gives OH⁻, not H⁺: start with pOH = −log[OH⁻].']]})}
 return q}
function bloodCalcQ(){const p=pick([7.20,7.25,7.30,7.32,7.48,7.50,7.55,7.60,7.38,7.42]),h=Number((10**-p).toPrecision(3)),pp=pHof(h),d=pp<7.35?'acidosis':pp>7.45?'alkalosis':'normal';
 const pr=pp.toFixed(3),mir=(14-pp).toFixed(3),D={acidosis:'acidosis (too acidic)',alkalosis:'alkalosis (too basic)',normal:'normal'};const other=d==='normal'?'acidosis':'normal',other2=d==='alkalosis'?'acidosis':'alkalosis';
 return mc({topic:'phc',video:'ph',prompt:`A patient's blood has [H₃O⁺] = ${sci(h,3)} M. What is the pH, and is it acidosis, alkalosis, or normal? (Normal arterial blood: 7.35–7.45.)`,hint:'pH = −log[H₃O⁺] (3 sig figs → 3 decimal places). Below 7.35 = acidosis; above 7.45 = alkalosis.',
  choices:[[`pH ${pr}: ${D[d]}`,true,`pH = −log(${sci(h,3)}) = ${pr}, which is ${d==='normal'?'inside':d==='acidosis'?'below':'above'} 7.35–7.45: ${D[d]}.`],[`pH ${pr}: ${D[other]}`,false,`The pH ${pr} is right, but compare it with 7.35–7.45: it is ${D[d]}.`],[`pH ${pr}: ${D[other2]}`,false,`The pH ${pr} is right, but compare it with 7.35–7.45: it is ${D[d]}.`],[`pH ${mir}: ${D[d]}`,false,`${mir} is 14 − pH (the pOH). pH = −log[H₃O⁺] = ${pr}.`]]})}
function calcModeQ(){return Math.random()<0.12?bloodCalcQ():calcQ()}

/* ---------- 🔄 Proton Pairs ---------- */
/* Brønsted–Lowry picture: the reaction drawn in SVG. After the answer, a curved arrow labeled H⁺ shows the proton
   moving from the acid to the base (an H⁺ ball travels along it), role tags appear under each species, and brackets
   join each conjugate pair (acid ↔ conjugate base in coral, base ↔ conjugate acid in blue). */
const BL_X=[80,240,420,580],BL_COL={A:'#c0392b',CB:'#c0392b',B:'#1f6aa5',CA:'#1f6aa5'};
function blDiagram(rx){const X=BL_X,ix=r=>rx.findIndex(x=>x[1]===r),a=ix('A'),b=ix('B'),ca=ix('CA'),cb=ix('CB');
 const txt=(x,y,t,o='')=>`<text x="${x}" y="${y}" text-anchor="middle" ${o}>${t}</text>`;
 const arc=`M${X[a]},74 C${X[a]},22 ${X[b]},22 ${X[b]},74`;
 /* bracket lines first, then labels on top; each label slides along its line away from the other bracket's verticals */
 const P=[[a,cb,170,BL_COL.A,'conjugate pair 1'],[b,ca,200,BL_COL.B,'conjugate pair 2']];
 const line=([i,j,d,c])=>`<path d="M${X[i]},144 V${d} H${X[j]} V144" fill="none" stroke="${c}" stroke-width="3" stroke-linejoin="round"/>`;
 const lab=([i,j,d,c,t],k)=>{const o=P[1-k],avoid=[X[o[0]],X[o[1]]],lo=Math.min(X[i],X[j])+72,hi=Math.max(X[i],X[j])-72;let best=(X[i]+X[j])/2,bd=-1;
  for(let x=lo;x<=hi;x+=5){const dd=Math.min(...avoid.map(v=>Math.abs(v-x)));if(dd>bd+0.5||(Math.abs(dd-bd)<=0.5&&Math.abs(x-(X[i]+X[j])/2)<Math.abs(best-(X[i]+X[j])/2))){bd=dd;best=x}}
  return `<rect x="${best-70}" y="${d-12}" width="140" height="24" rx="12" fill="#fff" stroke="${c}" stroke-width="1.5"/>`+txt(best,d+5,t,`font-size="15.5" font-weight="800" fill="${c}"`)};
 const alt=`${rx[0][0]} + ${rx[1][0]} ⇌ ${rx[2][0]} + ${rx[3][0]}`;
 return `<svg class="blsvg" viewBox="0 0 660 214" role="img" aria-label="${esc(alt)}"><defs><marker id="blHead" viewBox="0 0 10 10" refX="7" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="#e0675a"/></marker></defs>
 <g font-family="Inter,system-ui,sans-serif" font-weight="900" font-size="27" fill="#22313b">${txt(X[0],108,rx[0][0])}${txt(160,108,'+')}${txt(X[1],108,rx[1][0])}${txt(330,108,'⇌')}${txt(X[2],108,rx[2][0])}${txt(500,108,'+')}${txt(X[3],108,rx[3][0])}</g>
 <g class="blReveal" aria-hidden="true" style="opacity:0;transition:opacity .4s">
  <path id="blArc" d="${arc}" fill="none" stroke="#e0675a" stroke-width="3.5" stroke-dasharray="7 5" marker-end="url(#blHead)"/>
  ${txt((X[a]+X[b])/2,20,'H⁺ moves',`font-size="17" font-weight="800" fill="#c0504a"`)}
  <g class="blBall"><circle r="13" fill="#f9c4bf" stroke="#e0675a" stroke-width="2.5"/>${txt(0,5,'H⁺',`font-size="12" font-weight="900" fill="#22313b"`)}<animateMotion dur="1.4s" begin="indefinite" fill="freeze" rotate="0"><mpath href="#blArc"/></animateMotion></g>
  <g font-family="Inter,system-ui,sans-serif">${rx.map(([s,r],i)=>txt(X[i],138,ROLE_NAME[r],`font-size="17" font-weight="800" fill="${BL_COL[r]}"`)).join('')}
  ${P.map(line).join('')}${P.map(lab).join('')}</g></g></svg>`}
function labelQ(rx){rx=rx||pickNew('bl',BL_RX);const f=r=>rx.find(x=>x[1]===r)[0],A=f('A'),B=f('B'),CA=f('CA'),CB=f('CB');
 const msg={A:`${A} gives away an H⁺ and becomes ${CB}: it is the <b>acid</b>.`,B:`${B} picks up the H⁺ and becomes ${CA}: it is the <b>base</b>.`,CA:`${CA} is ${B} with one extra H⁺ (it can give it back): the <b>conjugate acid</b>.`,CB:`${CB} is ${A} after losing one H⁺: the <b>conjugate base</b>.`};
 return {type:'label',topic:'conj',video:'conj',rows:rx.map(([s,r])=>({f:s,want:r})),st:rx.map(()=>null),msg,
  prompt:'Label each species in this Brønsted–Lowry reaction.',html:blDiagram(rx),
  hint:'Find the reactant that LOSES an H⁺ (the acid); what it becomes is its conjugate base. The other reactant GAINS the H⁺ (the base) and becomes the conjugate acid.',
  why:`Pair 1: ${A} (acid) / ${CB} (conjugate base). Pair 2: ${B} (base) / ${CA} (conjugate acid). Each pair differs by one H⁺.`}}
function conjQ(){const L=pickNew('lad',LADDERS),wantBase=L.length===2?true:Math.random()<0.5;let i=wantBase?rnd(0,L.length-2):rnd(1,L.length-1);if(L.length===2)i=wantBase?0:1;
 const x=L[i],dir=wantBase?1:-1,r=L[i+dir],seen=new Set([sp(r)]),wr=[];const add=(e,why)=>{const t=typeof e==='string'?e:sp(e);if(!seen.has(t)&&wr.length<3){seen.add(t);wr.push([t,false,why])}};
 if(L[i-dir])add(L[i-dir],`That is the conjugate ${wantBase?'acid':'base'} (one H⁺ ${wantBase?'more':'less'}). The question asks for the conjugate ${wantBase?'base':'acid'}.`);
 if(L[i+2*dir])add(L[i+2*dir],`That ${wantBase?'removes':'adds'} two H⁺. A conjugate pair differs by exactly one H⁺.`);
 add([r[0],x[1]],wantBase?'You removed an H but kept the charge. Losing H⁺ also lowers the charge by 1.':'You added an H but kept the charge. Gaining H⁺ also raises the charge by 1.');
 add([x[0],r[1]],'The charge changed but the H count did not. A conjugate pair differs by one whole H⁺: one H and one + charge.');
 add([x[0],x[1]+(wantBase?1:-1)],'Charge goes the wrong way. Removing H⁺ makes it more negative; adding H⁺ makes it more positive.');
 return mc({topic:'conj',video:'conj',prompt:`What is the <b>conjugate ${wantBase?'base':'acid'}</b> of ${sp(x)}?`,hint:wantBase?'Conjugate base = take away one H⁺: one fewer H and the charge goes down by 1.':'Conjugate acid = add one H⁺: one more H and the charge goes up by 1.',
  choices:[[sp(r),true,`${wantBase?'Remove':'Add'} one H⁺: ${sp(x)} ${wantBase?'−':'+'} H⁺ → ${sp(r)}. One ${wantBase?'fewer':'more'} H, and the charge goes ${wantBase?'down':'up'} by 1.`],...wr]})}
function arrEqQ(){if(Math.random()<0.5){const a=pick(['Cl','Br','I','NO3','ClO4']),A=ANIONS[a],F=acidF(A),X=A[0];
  return mc({topic:'arr',video:'arr',prompt:`Which equation shows <b>${F}</b> acting as an <b>Arrhenius acid</b> in water?`,hint:'An Arrhenius acid produces H⁺ ions in water. The charges on the ions must add to zero.',
   choices:[[`${F}(aq) → H⁺(aq) + ${X}⁻(aq)`,true,`An Arrhenius acid releases H⁺ in water: ${F} → H⁺ + ${X}⁻. The charges balance (+1 and −1).`],[`${F}(aq) → H⁻(aq) + ${X}⁺(aq)`,false,'The charges are backward. The acid releases H<b>⁺</b>; the leftover anion is negative.'],[`${F}(aq) → H(aq) + ${X}(aq)`,false,'Arrhenius acids make ions, not neutral atoms. Neutral pieces would not conduct electricity.'],[`${F}(aq) → OH⁻(aq) + ${X}⁺(aq)`,false,'An acid releases H⁺, not OH⁻. Releasing OH⁻ is what an Arrhenius base does.']]})}
 const c=pick(['Na','K','Li','Ca','Ba','Sr']),C=CATIONS[c],F=baseF(C),M=C[0],n=C[1];
 return mc({topic:'arr',video:'arr',prompt:`Which equation shows <b>${F}</b> acting as an <b>Arrhenius base</b> in water?`,hint:`An Arrhenius base releases OH⁻ ions. Hydroxide (OH⁻) stays together as one ion${n>1?'; count how many there are':''}.`,
  choices:[[`${F}(aq) → ${M}${chg(n)}(aq) + ${cf(n)}OH⁻(aq)`,true,`An Arrhenius base releases OH⁻ in water: ${F} → ${M}${chg(n)} + ${cf(n)}OH⁻.`],
   [`${F}(aq) → ${M}${chg(n)}(aq) + ${cf(n)}O²⁻(aq) + ${cf(n)}H⁺(aq)`,false,'Hydroxide stays together as OH⁻; it does not split into O²⁻ and H⁺. Releasing H⁺ is what an acid does.'],
   [`${F}(aq) → ${M}${chg(-n)}(aq) + ${cf(n)}OH⁺(aq)`,false,'The charges are backward: metals form positive ions, and hydroxide is OH⁻.'],
   n>1?[`${F}(aq) → ${M}${chg(n)}(aq) + (OH)₂²⁻(aq)`,false,`The two OH⁻ ions are separate ions: write 2 OH⁻, not (OH)₂²⁻.`]:[`${F}(aq) → ${M}O⁻(aq) + H⁺(aq)`,false,'That releases H⁺, which would make it an acid. An Arrhenius base releases OH⁻.']]})}
const ARR_IDEAS=[
 {p:'By the <b>Arrhenius</b> definition, an acid is a substance that…',h:'Arrhenius: think about what ion appears in water.',c:[['Produces H⁺ when dissolved in water',true,'Arrhenius acids produce H⁺ (H₃O⁺) in water; Arrhenius bases produce OH⁻.'],['Accepts H⁺ from another substance',false,'Accepting H⁺ is a Brønsted–Lowry base.'],['Produces OH⁻ when dissolved in water',false,'Producing OH⁻ makes an Arrhenius base.'],['Contains at least one O atom',false,'HCl has no O and is still an acid. The definition is about making H⁺.']]},
 {p:'NH₃ is a base, but it is <b>not</b> an Arrhenius base. Why?',h:'Does NH₃ contain OH⁻ that it can release?',c:[['It has no OH⁻ to release; it accepts H⁺',true,'NH₃ has no hydroxide. It acts as a base by accepting H⁺ from water (Brønsted–Lowry), which makes OH⁻ indirectly.'],['It acts as a strong acid in water',false,'NH₃ is a weak base, not an acid.'],['It does not dissolve in water at all',false,'NH₃ dissolves very well in water (household ammonia).'],['It releases H⁺ ions when it dissolves',false,'Releasing H⁺ would make it an acid. NH₃ accepts H⁺.']]},
 {p:'Methanol, CH₃OH, has an "OH" in its formula. Is it an Arrhenius base?',h:'Is the OH an ion or a covalent group?',c:[['No: its O–H is covalent, not OH⁻',true,'In alcohols the –OH is covalently bonded to carbon. It does not come off as OH⁻ ion, so CH₃OH is not a base.'],['Yes: anything with OH is a base',false,'Only ionic hydroxides (like NaOH) release OH⁻. The –OH in an alcohol stays attached.'],['Yes, but only a weak Arrhenius base',false,'CH₃OH releases no OH⁻ at all, so it is not an Arrhenius base.'],['No: it is a strong acid instead',false,'Methanol is neither an acid nor a base in water.']]},
 {p:'Which definition calls an acid a <b>proton (H⁺) donor</b>?',h:'Which definition talks about transferring H⁺?',c:[['Brønsted–Lowry',true,'Brønsted–Lowry: acids donate H⁺ and bases accept H⁺.'],['Arrhenius',false,'Arrhenius talks about producing H⁺ or OH⁻ in water, not donating to a partner.'],['Le Châtelier (equilibrium)',false,'Le Châtelier\'s principle is about equilibrium shifts, not acids.'],['Avogadro',false,'Avogadro is about moles and gas volumes.']]},
 {p:'Which substance is an <b>Arrhenius base</b>?',h:'Look for a metal with hydroxide, OH⁻.',c:[['KOH',true,'KOH dissolves into K⁺ and OH⁻: it produces OH⁻ in water.'],['NH₃',false,'NH₃ is a Brønsted–Lowry base: it has no OH⁻ of its own.'],['CH₃CH₂OH',false,'Ethanol\'s –OH is covalent; it releases no OH⁻.'],['HNO₃',false,'HNO₃ is an acid: it produces H⁺.']]},
 {p:'In the reaction NH₃ + H₂O ⇌ NH₄⁺ + OH⁻, what does <b>water</b> act as?',h:'Does water give or take the H⁺ here?',c:[['An acid (it donates H⁺ to NH₃)',true,'H₂O gives an H⁺ to NH₃ and becomes OH⁻: here water is the Brønsted–Lowry acid.'],['A base (it accepts H⁺ from NH₃)',false,'NH₃ gains the H⁺ (it becomes NH₄⁺), so NH₃ is the base.'],['A spectator; it does not react',false,'Water loses an H⁺ and becomes OH⁻, so it reacts.'],['A salt',false,'Water is not a salt; here it is the acid.']]},
 {p:'Water can act as an acid <b>or</b> a base depending on its partner. This is called…',h:'Slide 14: water is ___.',c:[['Amphoteric',true,'Amphoteric substances (like H₂O and HCO₃⁻) can donate or accept H⁺.'],['Neutralization',false,'Neutralization is acid + base → salt + water.'],['A strong electrolyte',false,'Pure water has very few ions; it is a very weak electrolyte.'],['A buffer',false,'A buffer is a weak acid with its conjugate base.']]}];
function pairPickQ(){const L=pick(LADDERS),i=rnd(0,L.length-2),r=`${sp(L[i])} / ${sp(L[i+1])}`;
 const bad=[['H₃O⁺ / OH⁻','These differ by two H⁺ (H₃O⁺ → H₂O → OH⁻). A conjugate pair differs by one H⁺.'],['HCl / NaOH','That is an acid and a base that react, but they are not related by one H⁺.'],['H₂SO₄ / SO₄²⁻','These differ by two H⁺. The conjugate base of H₂SO₄ is HSO₄⁻.'],['NH₄⁺ / NH₂⁻','These differ by two H⁺. The conjugate base of NH₄⁺ is NH₃.'],['HNO₃ / HNO₂','These differ by an O atom, not an H⁺.'],['H₂O / H₂O₂','Water and peroxide differ by an O atom, not an H⁺.'],['H₃PO₄ / PO₄³⁻','These differ by three H⁺.']].filter(b=>b[0]!==r);
 return mc({topic:'conj',video:'conj',prompt:'Which is a <b>conjugate acid–base pair</b>?',hint:'A conjugate pair differs by exactly ONE H⁺ (one H atom and one unit of charge).',choices:[[r,true,`${sp(L[i])} loses one H⁺ to become ${sp(L[i+1])}: they differ by exactly one H⁺.`],...shuf(bad).slice(0,3).map(b=>[b[0],false,b[1]])]})}
function pairsQ(){const r=Math.random();if(r<0.32)return labelQ();if(r<0.57)return conjQ();if(r<0.72)return arrEqQ();if(r<0.87){const it=pickNew('arr',ARR_IDEAS);return fx(Object.assign({v:'arr',t:'arr'},it))}if(r<0.93)return defsQ();return pairPickQ()}

/* ---------- ⚗️ Titration Lab ---------- */
const TIT_ACIDS=[['HCl',1,null],['HNO₃',1,null],['H₂SO₄',2,null],['CH₃COOH',1,1.8e-5]];
const TIT_EQ={'HCl':'HCl + NaOH → NaCl + H₂O','HNO₃':'HNO₃ + NaOH → NaNO₃ + H₂O','H₂SO₄':'H₂SO₄ + 2 NaOH → Na₂SO₄ + 2 H₂O','CH₃COOH':'CH₃COOH + NaOH → NaCH₃COO + H₂O'};
function titNums(r){for(let k=0;k<50;k++){const Cb=pick([0.100,0.150,0.200]),Va=pick([20.0,25.0]),want=rnd(14,38),Ca=Number((want*Cb/(r*Va)).toPrecision(3)),Veq=r*Ca*Va/Cb;if(Ca>=0.03&&Ca<=0.5&&Veq>10&&Veq<44)return {Cb,Va,Ca,Veq}}return {Cb:0.100,Va:20.0,Ca:0.150,Veq:30*(3-r)/2}}
function titAns(q,V){const c=q.cfg;return c.Cb*V/1000/c.r/(c.Va/1000)}
function titLabQ(){const [af,r,Ka]=pick(TIT_ACIDS),n=titNums(r),cfg={acidF:af,baseF:'NaOH',r,m:1,Ka,Ca:n.Ca,Va:n.Va,Cb:n.Cb};const Vdef=Math.round(n.Veq*100)/100;
 const q={type:'num',kind:'conc',sf:3,unit:'M',topic:'tit',video:'titr',cfg,lab:{kind:'tit',cfg},task:{need:'endpoint',say:'Titrate: add NaOH until the flask turns <b>faint pink</b> and stays pink. Big steps first, then drops near the end.'},
  prompt:`What is the molarity of the ${af}? Titrate first, then use your buret reading.`,
  html:`<div class="rxn">${TIT_EQ[af]}</div><div class="givens"><span>${n.Va.toFixed(1)} mL ${af}</span><span>${n.Cb.toFixed(3)} M NaOH</span><span>NaOH used: <b class="titV">— titrate first</b></span></div>`,
  hint:`mol NaOH = M × L. Use the mole ratio (${r===2?'1 H₂SO₄ : 2 NaOH':'1 : 1'}), then divide by the acid volume in liters (${(n.Va/1000).toFixed(4)} L).`,V:Vdef};
 q.answer=titAns(q,Vdef);q.mkWhy=()=>{const V=q.V,mb=n.Cb*V/1000,ma=mb/r;q.why=`mol NaOH = ${n.Cb.toFixed(3)} M × ${(V/1000).toFixed(5)} L = ${nf(mb,3)} mol. ${r===2?`mol H₂SO₄ = ${nf(mb,3)} ÷ 2 = ${nf(ma,3)} mol.`:`1 : 1, so mol ${af} = ${nf(ma,3)} mol.`} M = ${nf(ma,3)} mol ÷ ${(n.Va/1000).toFixed(4)} L = <b>${nf(ma/(n.Va/1000),3)} M</b>.`;
  q.slips=[[q.answer*r,r===2?'Use the mole ratio: 2 NaOH react with each H₂SO₄, so divide the moles of NaOH by 2.':''],[n.Cb*n.Va/V,'The volumes are switched: mol NaOH = M<sub>NaOH</sub> × V<sub>NaOH</sub>.'],[q.answer*1000,'Convert mL to L (÷ 1000) before finding moles.'],[q.answer/1000,'Use the same volume units: divide moles by the acid volume in liters.']]};
 q.mkWhy();q.onTask=L=>{q.V=L.endV;q.answer=titAns(q,L.endV);q.mkWhy();document.querySelectorAll('.titV').forEach(e=>e.textContent=L.endV.toFixed(2)+' mL')};return q}
const BIGB=[['NaOH',1],['KOH',1],['Ba(OH)₂',2],['Ca(OH)₂',2]];
function titCalcQ(){const [af,r]=pick([['HCl',1],['HNO₃',1],['H₂SO₄',2],['HBr',1]]),[bf,m]=pick(BIGB.filter(b=>!(af==='H₂SO₄'&&b[1]===2))),Va=pick([10.0,20.0,25.0,50.0]),Cb=pick([0.100,0.150,0.200,0.250]),Vb=rnd(1200,4500)/100,Ca=Cb*Vb*m/(r*Va);
 const ratio=r===m?'1 : 1':r===2?`1 ${af} : 2 ${bf}`:`2 ${af} : 1 ${bf}`,eq=r===m?`${af} + ${bf} → salt + ${cf(r)}H₂O`:r===2?`${af} + 2 ${bf} → salt + 2 H₂O`:`2 ${af} + ${bf} → salt + 2 H₂O`;
 if(Math.random()<0.2)return massTitQ();if(Math.random()<0.65)return {type:'num',kind:'conc',sf:3,unit:'M',topic:'tit',video:'titrRatio',html:`<div class="rxn">${eq}</div>`,prompt:`In a titration, ${Vb.toFixed(2)} mL of ${Cb.toFixed(3)} M ${bf} completely neutralizes ${Va.toFixed(1)} mL of ${af}. What is the molarity of the ${af}?`,answer:Ca,
  hint:`mol ${bf} = M × L, then use the mole ratio ${ratio}, then divide by the acid volume in liters.`,why:`mol ${bf} = ${Cb.toFixed(3)} × ${(Vb/1000).toFixed(5)} L = ${nf(Cb*Vb/1000,3)} mol → mol ${af} = ${nf(Cb*Vb/1000*m/r,3)} mol (${ratio}) → M = ÷ ${(Va/1000).toFixed(4)} L = <b>${nf(Ca,3)} M</b>.`,
  slips:[[Cb*Vb/Va,r!==m?`Use the mole ratio ${ratio}; M₁V₁ = M₂V₂ only works for 1 : 1.`:''],[Cb*Va/Vb,'The volumes are switched.'],[Ca*1000,'Convert mL to L before finding moles.']].filter(s=>s[1])};
 const Ca2=Number((Ca).toPrecision(3)),V=r*Ca2*Va/(m*Cb);
 return {type:'num',kind:'conc',sf:3,unit:'mL',topic:'tit',video:'titr',html:`<div class="rxn">${eq}</div>`,prompt:`What volume of ${Cb.toFixed(3)} M ${bf} is needed to neutralize ${Va.toFixed(1)} mL of ${nf(Ca2,3)} M ${af}?`,answer:V,
  hint:`mol ${af} = M × L, use the ratio ${ratio}, then L of base = mol ÷ M. Answer in mL.`,why:`mol ${af} = ${nf(Ca2,3)} × ${(Va/1000).toFixed(4)} L = ${nf(Ca2*Va/1000,3)} mol → mol ${bf} = ${nf(Ca2*Va/1000*r/m,3)} mol → V = ÷ ${Cb.toFixed(3)} M = ${nf(V/1000,3)} L = <b>${nf(V,3)} mL</b>.`,
  slips:[[V/1000,'The answer is in mL: multiply liters by 1000.'],[Ca2*Va/Cb,r!==m?`Use the mole ratio ${ratio}.`:''],[Cb*Va/Ca2,'Flip it: V<sub>base</sub> = mol ÷ M<sub>base</sub>.']].filter(s=>s[1])}}
function neutQ(){for(;;){const a=pick(['Cl','Br','NO3','ClO4','SO4']),c=pick(['Na','K','Li','Ca','Ba','Sr']),A=ANIONS[a],C=CATIONS[c],n=A[1],m=C[1],L=n*m/gcd(n,m),ca=L/n,cb=L/m,AF=acidF(A),BF=baseF(C),S=saltF(C,A);
 const lhs=`${cf(ca)}${AF} + ${cf(cb)}${BF}`,right=`${lhs} → ${S} + ${cf(L)}H₂O`,W=[];
 if(n!==m)W.push([`${lhs} → ${C[0]}${A[0]} + ${cf(L)}H₂O`,`Crisscross the charges: ${C[0]}${chg(m)} and ${A[0]}${chg(-n)} make ${S}, not ${C[0]}${A[0]}.`]);
 if(L>1)W.push([`${AF} + ${BF} → ${S} + H₂O`,`Not balanced: ${L} H⁺ must meet ${L} OH⁻ to make ${L} H₂O. Count the H and O atoms.`]);
 W.push([`${lhs} → ${S} + ${cf(L)}H₂`,'H₂ gas forms when an acid reacts with a metal, not with a hydroxide. Acid + base → salt + <b>water</b>.']);
 W.push([`${lhs} → ${cf(L)}H₂O + ${cf(L)}${C[0]}H`,`Water forms, and the leftover ions ${C[0]}${chg(m)} and ${A[0]}${chg(-n)} make the salt ${S}. Metals do not bond to H here.`]);
 if(W.length<4)W.push([`${lhs} → no reaction`,'Acids and bases always react: H⁺ + OH⁻ → H₂O (neutralization).']);
 return mc({topic:'neut',video:'stoich',prompt:`Which is the balanced <b>neutralization</b> equation for ${AF} and ${BF}?`,hint:'Acid + base → salt + water. Build the salt by crisscrossing the ion charges, then balance with water.',
  choices:[[right,true,`H⁺ + OH⁻ → H₂O, and the leftover ions ${C[0]}${chg(m)} and ${A[0]}${chg(-n)} form the salt ${S}. ${L} H⁺ + ${L} OH⁻ make ${L} H₂O.`],...W.slice(0,3).map(w=>[w[0],false,w[1]])]})}}
function metalQ(){const [M]=pick([['Mg',2],['Zn',2],['Fe',2],['Ca',2]]),a=pick(['Cl','SO4']),A=ANIONS[a],n=A[1],k=2/n,S=saltF([M,2],A),AF=acidF(A);
 return mc({topic:'neut',video:'props',prompt:`What forms when solid ${M} is dipped into ${AF}(aq)?`,hint:'Acids corrode metals in a single-replacement reaction: metal + acid → salt + hydrogen gas.',
  choices:[[`${M} + ${cf(k)}${AF} → ${S} + H₂`,true,`The metal replaces the H: ${M} + ${cf(k)}${AF} → ${S} + H₂(g). The bubbles are hydrogen gas.`],[`${M} + ${cf(k)}${AF} → ${S} + H₂O`,false,'Water forms when an acid meets a base (OH⁻). A metal + acid gives H₂ gas.'],[`${M} + ${AF} → ${M}${A[0]} + H`,false,n===1?`Crisscross the charges (${M}²⁺, ${A[0]}⁻) to get ${S}, and hydrogen leaves as H₂ gas.`:'Hydrogen leaves as H₂ gas (a diatomic molecule), not as single H atoms.'],[`${M} + ${cf(k)}${AF} → no reaction`,false,'Acids corrode (dissolve) metals like Mg, Zn and Fe.']]})}
const TIT_IDEAS=[
 {p:'Nitric acid neutralizes sodium carbonate: 2 HNO₃ + Na₂CO₃ → ? What are the products?',h:'Acid + carbonate → salt + water + carbon dioxide gas.',c:[['2 NaNO₃ + H₂O + CO₂',true,'H⁺ turns CO₃²⁻ into H₂CO₃, which breaks into H₂O and CO₂ gas (the fizz). Na⁺ and NO₃⁻ make the salt NaNO₃.'],['Na₂NO₃ + H₂CO₃ only',false,'Na⁺ and NO₃⁻ make NaNO₃ (one each), and H₂CO₃ falls apart into H₂O + CO₂.'],['2 NaNO₃ + H₂ + CO₃',false,'H₂ gas comes from acid + metal. Carbonate gives H₂O and CO₂.'],['2 NaOH + N₂O₅ + CO₂',false,'Neutralization makes a salt; it does not make NaOH or nitrogen oxides.']]},
 {p:'In a titration, what is the <b>titrant</b>?',h:'Which solution goes in the buret?',c:[['The known solution in the buret',true,'The titrant (like 0.100 M NaOH) is in the buret; its concentration is known.'],['The unknown acid sitting in the flask',false,'The unknown is the analyte in the flask.'],['The indicator',false,'The indicator only shows the endpoint by changing color.'],['The water used to rinse',false,'Rinse water is not part of the measurement.']]},
 {p:'What has happened at the <b>endpoint</b> of an acid–base titration?',h:'Lecture 27 slide 14.',c:[['Moles of OH⁻ added = moles of H⁺',true,'At the endpoint the base has used up all the acid: mol OH⁻ = mol H⁺, and the indicator changes color.'],['The buret is completely empty',false,'You usually stop long before the buret is empty.'],['The volumes of acid and base are equal',false,'Moles must match, not volumes. Different molarities need different volumes.'],['The solution boils',false,'Neutralization gives off a little heat, but nothing boils.']]},
 {p:'Why add the base <b>drop by drop</b> near the end of a titration?',h:'What happens one drop past the endpoint?',c:[['One extra drop can overshoot the color change',true,'Near the endpoint, one drop changes the pH by several units. Going slowly lets you stop at faint pink.'],['Single drops react faster than a stream',false,'Each drop reacts just as fast; going slowly is about not overshooting.'],['To keep the flask from getting too hot to hold',false,'The heat is tiny. Precision is the reason.'],['Because the indicator runs out',false,'The indicator does not get used up.']]},
 {p:'Which net ionic equation describes every strong acid + strong base neutralization?',h:'Which ions actually change?',c:[['H⁺ + OH⁻ → H₂O',true,'The metal ion and the anion are spectators; H⁺ and OH⁻ combine to make water.'],['Na⁺ + Cl⁻ → NaCl',false,'Na⁺ and Cl⁻ stay dissolved as spectator ions.'],['H⁺ + H⁺ → H₂',false,'H₂ gas comes from an acid + metal, not acid + base.'],['OH⁻ + OH⁻ → H₂O₂',false,'Hydroxide ions do not combine to make peroxide.']]},
 {p:'Milk of magnesia, Mg(OH)₂, relieves heartburn from stomach acid, HCl. What are the products?',h:'Acid + base → salt + water.',c:[['MgCl₂ + 2 H₂O',true,'Mg(OH)₂ + 2 HCl → MgCl₂ + 2 H₂O: neutralization makes a salt and water.'],['MgCl + H₂O',false,'Crisscross Mg²⁺ and Cl⁻: the salt is MgCl₂, and balancing gives 2 H₂O.'],['Mg + Cl₂ + H₂',false,'Neutralization does not make elements; it makes a salt and water.'],['MgO + 2 HCl',false,'HCl is used up, not made, when the antacid works.']]},
 {p:'Why does a titration with phenolphthalein start <b>colorless</b>?',h:'Where is the acid at the start?',c:[['The flask holds acid, and it is colorless in acid',true,'The unknown acid is in the flask, and phenolphthalein is colorless in acid. It turns pink only after all the acid is used up.'],['The base has not been added to the flask yet',false,'The base is already in the buret.'],['Phenolphthalein is colorless at every pH',false,'It turns pink in base (above pH 8.2).'],['The flask holds a base, which is colorless',false,'In this setup the flask holds the acid.']]}];
function titrateQ(){const r=Math.random();if(r<0.38)return titLabQ();if(r<0.6)return titCalcQ();if(r<0.78)return neutQ();if(r<0.86)return metalQ();return fx(Object.assign({v:'titr',t:'tit'},pickNew('tit',TIT_IDEAS)))}

