function ionConcQ(){const it=pick([['HCl',1,'SA'],['HNO₃',1,'SA'],['HBr',1,'SA'],['NaOH',1,'SB'],['KOH',1,'SB'],['Ca(OH)₂',2,'SB'],['Ba(OH)₂',2,'SB'],['HF',1,'WA'],['CH₃COOH',1,'WA'],['HNO₂',1,'WA']]),C=pick([0.10,0.50,1.5,2.0,3.0]),cs=C.toFixed(C<1?2:1),ion=it[2]==='SB'?'[OH⁻]':'[H₃O⁺]',f=x=>Number(x.toPrecision(2)).toFixed(C<1?2:1);
 const one=`${cs} M`,two=`${f(2*C)} M`,less=`Less than ${cs} M`,more=`More than ${f(2*C)} M`;
 const right=it[2]==='WA'?less:it[1]===2?two:one,per=it[2]==='SB'?'OH⁻':'H₃O⁺';
 const why={[less]:it[2]==='WA'?`${it[0]} is a weak acid: only a small fraction ionizes, so ${ion} is much less than ${cs} M.`:`${it[0]} is strong: it ionizes 100%, so ${ion} is not less than ${cs} M.`,
  [one]:it[2]==='WA'?`That would be true only if ${it[0]} ionized 100%. It is weak.`:it[1]===2?`Each ${it[0]} releases <b>2</b> OH⁻, so ${ion} = 2 × ${cs} = ${f(2*C)} M.`:`${it[0]} is strong and gives one ${per} per formula: ${ion} = ${cs} M.`,
  [two]:it[1]===2?`Each ${it[0]} releases 2 OH⁻: 2 × ${cs} = ${f(2*C)} M.`:`${it[0]} gives only one ${per} per formula unit, not two.`,
  [more]:'A substance cannot release more ions than it has: at most one per H or OH it can give off.'};
 return mc({topic:'strong',video:'strength',keepOrder:true,prompt:`What is ${ion} in ${cs} M ${it[0]}(aq)?`,hint:'Strong acids and bases ionize 100%. Count how many H⁺ or OH⁻ each formula gives. Weak acids ionize only a little.',choices:[less,one,two,more].map(w=>[w,w===right,why[w]])})}
const DEFS=[['HCl','AA'],['HNO₃','AA'],['HBr','AA'],['CH₃COOH','AA'],['HF','AA'],['NaOH','AB'],['KOH','AB'],['Ba(OH)₂','AB'],['NH₃','BB'],['CH₃NH₂','BB'],['MgCl₂','S'],['NaCl','S'],['KNO₃','S'],['CH₄','M'],['CH₃OH','M'],['C₆H₁₂O₆','M']];
const DEF_TXT={AA:'Arrhenius acid and Brønsted–Lowry acid',AB:'Arrhenius base and Brønsted–Lowry base',BB:'Brønsted–Lowry base only',S:'Neither: it is a salt',M:'Neither: it is a molecular compound'};
function defsQ(){const [f,k]=pick(DEFS);
 const W={AA:`${f} makes H⁺ in water (Arrhenius) and donates H⁺ (Brønsted–Lowry): both acid definitions fit.`,AB:`${f} releases OH⁻ in water (Arrhenius), and that OH⁻ accepts H⁺ (Brønsted–Lowry): both base definitions fit.`,BB:`${f} has no OH⁻ to release, so it is not an Arrhenius base, but its N lone pair accepts H⁺: a Brønsted–Lowry base.`,S:`${f} is ionic, but its ions are neither H⁺ nor OH⁻ and do not trade H⁺: a salt.`,M:`${f} is covalent and does not give off or accept H⁺ in water: a molecular compound.`};
 const isAc=k==='AA',isBs=k==='AB'||k==='BB';
 const wrongWhy={AA:`An acid must give off H⁺, and ${f} does not.`,AB:k==='BB'?`An Arrhenius base must release OH⁻ ions; ${f} has no hydroxide ion.`:`${f} has no hydroxide ion to release, so it is not an Arrhenius base.`,BB:k==='AB'?`${f} does release OH⁻, so it is ALSO an Arrhenius base, not "Brønsted–Lowry only."`:`A Brønsted–Lowry base accepts H⁺; ${f} does not.`,
  S:k==='M'?`${f} is covalent (no metal or ammonium ion), so it is not a salt.`:isAc?`${f} is an acid, not a neutral salt.`:isBs?`${f} is a base, not a neutral salt.`:'',M:k==='S'?`${f} is ionic (a metal with a nonmetal), so it is a salt, not a molecular compound.`:isAc?`${f} gives off H⁺, so it is an acid.`:isBs?`${f} accepts H⁺, so it is a base.`:''};
 const others=shuf(Object.keys(DEF_TXT).filter(x=>x!==k)).slice(0,3);
 return mc({topic:'arr',video:'arr',prompt:`Which acid–base definitions does <b>${f}</b> meet?`,hint:'Arrhenius: makes H⁺ or OH⁻ in water. Brønsted–Lowry: donates or accepts H⁺. Ionic with no H⁺/OH⁻ = salt; covalent with neither = molecular.',choices:[[DEF_TXT[k],true,W[k]],...others.map(o=>[DEF_TXT[o],false,wrongWhy[o]])]})}
function massTitQ(){const [bf,MM]=pick([['Mg(OH)₂',58.33],['Ca(OH)₂',74.10]]),g=rnd(100,400)/100,M=pick([0.100,0.125,0.150,0.200,0.250]),mol=g/MM,V=mol*2/M*1000;
 return {type:'num',kind:'conc',sf:3,unit:'mL',topic:'tit',video:'titrRatio',html:`<div class="rxn">2 HCl + ${bf} → ${bf==='Mg(OH)₂'?'MgCl₂':'CaCl₂'} + 2 H₂O</div><div class="givens"><span>Molar mass ${bf} = ${MM.toFixed(2)} g/mol</span></div>`,
  prompt:`What volume of ${M.toFixed(3)} M HCl neutralizes ${g.toFixed(2)} g of ${bf} (an antacid)?`,answer:V,hint:`grams → moles (÷ ${MM.toFixed(2)} g/mol) → mol HCl (× 2) → liters (÷ ${M.toFixed(3)} M) → mL.`,
  why:`${g.toFixed(2)} g ÷ ${MM.toFixed(2)} g/mol = ${nf(mol,3)} mol ${bf} → × 2 = ${nf(2*mol,3)} mol HCl → ÷ ${M.toFixed(3)} M = ${nf(V/1000,3)} L = <b>${nf(V,3)} mL</b>.`,
  slips:[[V/2,'Use the mole ratio: each '+bf+' needs 2 HCl.'],[V/1000,'Convert liters to mL (× 1000).'],[g/M*1000,'Change grams to moles first, using the molar mass.']]}}
