const TOPICS={id:['Identifying acids and bases','id','props'],strong:['Strong vs. weak acids and bases','id','strength'],arr:['Arrhenius definitions','pairs','props'],conj:['Conjugate acid–base pairs','pairs','conj'],
 ind:['Indicators and the pH scale','ph','ph'],phc:['pH and pOH calculations','calc','ph'],conc:['[H⁺] and [OH⁻] calculations','calc','log'],neut:['Neutralization reactions','titrate','stoich'],tit:['Titration calculations','titrate','titr'],buf:['Buffers','buffer','buffer']};
const QUIZ_PLAN=['id','strong','arr','conj','ind','phc','conc','neut','tit','buf'];
function topicQ(t){let q;
 if(t==='id')q=Math.random()<0.5?classifyQ():Math.random()<0.5?familyQ():fx(pick(PROPS));
 else if(t==='strong')q=pick([strongPickQ,ionConcQ,()=>classifyQ(pick(SUBST.filter(s=>s[1]!=='N')))])();
 else if(t==='arr')q=pick([arrEqQ,defsQ,()=>fx(Object.assign({v:'arr'},pick(ARR_IDEAS)))])();
 else if(t==='conj')q=pick([conjQ,labelQ,pairPickQ])();
 else if(t==='ind')q=Math.random()<0.5?concClassQ():fx(pick(PH_IDEAS.filter(x=>x.t==='ind')));
 else if(t==='phc')q=calcQ(pick(['pHH','pOHOH','pOHfrompH','pHfromOH','sa','sb']));
 else if(t==='conc')q=calcQ(pick(['Hfrom','HfrompOH','OHfromH']));
 else if(t==='neut')q=Math.random()<0.7?neutQ():metalQ();
 else if(t==='tit')q=titCalcQ();
 else q=Math.random()<0.6?isBufferQ():fx(pick(BUF_IDEAS));
 q.topic=t;return q}
const GEN={id:idQ,ph:phQ,calc:calcModeQ,pairs:pairsQ,titrate:titrateQ,buffer:bufferQ,quiz:()=>topicQ(state.quiz.plan[state.quiz.i])};
